    // Function to check if a number is prime
    function is_prime($n) {
        // Numbers less than 2 are not prime
        if ($n < 2) {
            return false;
        }
        // Check for factors up to the square root of n
        for ($i = 2; $i <= sqrt($n); $i++) {
            // If n is divisible by any of these numbers, it's not prime
            if ($n % $i == 0) {
                return false;
            }
        }
        // If no factors were found, n is prime
        return true;
    }

    // Get unique prime numbers from the array (ignoring negative signs)
    $primes = array_filter(array_unique($arr), function($x) {
        return is_prime(abs($x));
    });

    // If no prime numbers were found, return null
    if (empty($primes)) {
        return null;
    }

    // Calculate the sum of prime numbers that appear an even number of times
    // and subtract the sum of prime numbers that appear an odd number of times
    $sum = 0;
    foreach ($primes as $prime) {
        // Count the occurrences of the prime number in the array
