func longestSubstring(strings: [String], k: Int) -> String? {
    guard !strings.isEmpty else { return nil }
    var longestStr: String = ""
    for string in strings {
        let substrings = allSubstrings(inputString: string)
        for substring in substrings {
            let count = strings.filter { $0.contains(substring) }.count
            if count >= k && (longestStr.isEmpty || substring.count > longestStr.count) {
                longestStr = substring
            }
        }
    }
    return longestStr.isEmpty ? nil : longestStr
}
