**Creating a Node.js API with MongoDB to Serve Blog Posts**

To create an API using Node.js and MongoDB to serve a list of blog posts, follow these steps:

### Step 1: Set up the Project

Create a new Node.js project and install the required dependencies:
```bash
npm init -y
npm install express mongoose body-parser
```
### Step 2: Connect to MongoDB

Create a new file called `db.js` to connect to your MongoDB database:
```javascript
// db.js
const mongoose = require('mongoose');

const connectDB = async () => {
  try {
    await mongoose.connect('mongodb://localhost:27017/blog', {
      useNewUrlParser: true,
      useUnifiedTopology: true,
    });
    console.log('Connected to MongoDB');
  } catch (err) {
    console.error(err);
  }
};

module.exports = connectDB;
```
### Step 3: Define the Blog Post Model

Create a new file called `post.js` to define the blog post model:
```javascript
// post.js
const mongoose = require('mongoose');

const postSchema = new mongoose.Schema({
  title: String,
  text: String,
  author: String,
});

const Post = mongoose.model('Post', postSchema);

module.exports = Post;
```
### Step 4: Create the API Routes

Create a new file called `routes.js` to define the API routes:
```javascript
// routes.js
const express = require('express');
const router = express.Router();
const Post = require('./post');

// Get all blog posts
router.get('/posts', async (req, res) => {
  try {
    const posts = await Post.find();
    res.json(posts);
  } catch (err) {
    res.status(500).json({ message: 'Error fetching posts' });
  }
});

// Create a new blog post
router.post('/posts', async (req, res) => {
  try {
    const post = new Post(req.body);
    await post.save();
    res.json(post);
  } catch (err) {
    res.status(500).json({ message: 'Error creating post' });
  }
});

// Get a single blog post by ID
router.get('/posts/:id', async (req, res) => {
  try {
    const post = await Post.findById(req.params.id);
    if (!post) {
      res.status(404).json({ message: 'Post not found' });
    } else {
      res.json(post);
    }
  } catch (err) {
    res.status(500).json({ message: 'Error fetching post' });
  }
});

// Update a blog post
router.put('/posts/:id', async (req, res) => {
  try {
    const post = await Post.findByIdAndUpdate(req.params.id, req.body, {
      new: true,
    });
    if (!post) {
      res.status(404).json({ message: 'Post not found' });
    } else {
      res.json(post);
    }
  } catch (err) {
    res.status(500).json({ message: 'Error updating post' });
  }
});

// Delete a blog post
router.delete('/posts/:id', async (req, res) => {
  try {
    await Post.findByIdAndRemove(req.params.id);
    res.json({ message: 'Post deleted successfully' });
  } catch (err) {
    res.status(500).json({ message: 'Error deleting post' });
  }
});

module.exports = router;
```
### Step 5: Set up the Express Server

Create a new file called `app.js` to set up the Express server:
```javascript
// app.js
const express = require('express');
const app = express();
const connectDB = require('./db');
const routes = require('./routes');
const bodyParser = require('body-parser');

app.use(bodyParser.json());
app.use('/api', routes);

connectDB().then(() => {
  const port = 3000;
  app.listen(port, () => {
    console.log(`Server listening on port ${port}`);
  });
});
```
